def remove_adjacent_duplicate_pairs(lst):
    output = []
    for value in lst:
        if output and output[-1] == value:
            output.pop()
        else:
            output.append(value)
    return output

def is_valid_isbn13(s):
    digits = s.replace('-', '')
    if len(digits) != 13 or not digits.isdigit():
        return False
    checksum = sum(int(c) * (1 if idx % 2 == 0 else 3) for idx, c in enumerate(digits))
    return checksum % 10 == 0

