def is_valid_ipv4_address(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if part != '0' and part[0] == '0':
            return False
        if int(part) > 255:
            return False
    return True

