def average_by_key_from_pairs(pairs):
    totals = {}
    counts = {}
    for key, value in pairs:
        totals[key] = totals.get(key, 0) + value
        counts[key] = counts.get(key, 0) + 1
    averages = {}
    for key in totals:
        averages[key] = round(totals[key] / counts[key], 2)
    return averages

