def is_valid_ipv6_full(s):
    parts = s.split(':')
    if len(parts) != 8:
        return False
    hexchars = set('0123456789abcdefABCDEF')
    for part in parts:
        if not (1 <= len(part) <= 4):
            return False
        if any(c not in hexchars for c in part):
            return False
    return True

