def is_valid_hsl_tuple(t):
    if type(t) is not tuple or len(t) != 3:
        return False
    hue, sat, light = t
    if type(hue) is not int or not (0 <= hue <= 360):
        return False
    for component in (sat, light):
        if type(component) not in (int, float) or not (0 <= component <= 100):
            return False
    return True

